// Test-only public protobuf fixture encoder. Uses actual fixed Go messages.
package main
import("bufio";"encoding/base64";"encoding/json";"fmt";"os";"github.com/livekit/protocol/livekit";"google.golang.org/protobuf/encoding/protojson";"google.golang.org/protobuf/proto")
func main(){scanner:=bufio.NewScanner(os.Stdin);scanner.Buffer(make([]byte,4096),1<<20);for scanner.Scan(){var row struct{Name string `json:"name"`; Nodes []json.RawMessage `json:"nodes"`};if err:=json.Unmarshal(scanner.Bytes(),&row);err!=nil{panic(err)};if row.Nodes==nil{continue};values:=make([]string,0,len(row.Nodes));for _,body:=range row.Nodes{node:=new(livekit.Node);if err:=protojson.Unmarshal(body,node);err!=nil{panic(err)};wire,err:=proto.Marshal(node);if err!=nil{panic(err)};values=append(values,base64.StdEncoding.EncodeToString(wire))};out,err:=json.Marshal(map[string]any{"name":row.Name,"wire_base64":values});if err!=nil{panic(err)};fmt.Println(string(out))};if err:=scanner.Err();err!=nil{panic(err)}}
